'use client';

import * as ContextMenuPrimitive from '@radix-ui/react-context-menu';
import * as React from 'react';

import { Icon } from '@/components/ui/icon';
import { IconShell } from '@/components/ui/icon-shell';
import { cn } from '@/lib/utils';

type ContextMenuSize = 'default' | 'lg';

const ContextMenuSizeContext = React.createContext<ContextMenuSize>('default');

function useContextMenuSize() {
  return React.useContext(ContextMenuSizeContext);
}

function CheckboxItemMark() {
  return (
    <svg
      xmlns="http://www.w3.org/2000/svg"
      className="h-[7px] w-2"
      viewBox="0 0 8 7"
      fill="none">
      <path
        fillRule="evenodd"
        clipRule="evenodd"
        d="M7.5 1.25L6.25 0L2.5 3.75L1.25 2.5L0 3.75L2.5 6.25L7.5 1.25Z"
        fill="currentColor"
      />
    </svg>
  );
}

function ContextMenu({
  ...props
}: React.ComponentProps<typeof ContextMenuPrimitive.Root>) {
  return <ContextMenuPrimitive.Root data-slot="context-menu" {...props} />;
}

function ContextMenuPortal({
  ...props
}: React.ComponentProps<typeof ContextMenuPrimitive.Portal>) {
  return (
    <ContextMenuPrimitive.Portal data-slot="context-menu-portal" {...props} />
  );
}

function ContextMenuTrigger({
  ...props
}: React.ComponentProps<typeof ContextMenuPrimitive.Trigger>) {
  return (
    <ContextMenuPrimitive.Trigger data-slot="context-menu-trigger" {...props} />
  );
}

interface ContextMenuContentProps extends React.ComponentProps<
  typeof ContextMenuPrimitive.Content
> {
  children?: React.ReactNode;
  onOpenAutoFocus?: (event: Event) => void;
  size?: ContextMenuSize;
}

function ContextMenuContent({
  className,
  size = 'default',
  ...props
}: ContextMenuContentProps) {
  return (
    <ContextMenuPrimitive.Portal>
      <ContextMenuSizeContext.Provider value={size}>
        <ContextMenuPrimitive.Content
          data-slot="context-menu-content"
          data-size={size}
          className={cn(
            'bg-fill-active-inverse text-fg-primary shadow-elevation-2 data-[state=open]:animate-in data-[state=closed]:animate-out data-[state=closed]:fade-out-0 data-[state=open]:fade-in-0 data-[state=closed]:zoom-out-95 data-[state=open]:zoom-in-95 data-[side=bottom]:slide-in-from-top-2 data-[side=left]:slide-in-from-right-2 data-[side=right]:slide-in-from-left-2 data-[side=top]:slide-in-from-bottom-2 z-50 max-h-(--radix-context-menu-content-available-height) origin-(--radix-context-menu-content-transform-origin) overflow-x-hidden overflow-y-auto',
            size === 'lg' ? 'px-1 py-2' : 'p-1',
            className,
          )}
          {...props}
        />
      </ContextMenuSizeContext.Provider>
    </ContextMenuPrimitive.Portal>
  );
}

function ContextMenuGroup({
  ...props
}: React.ComponentProps<typeof ContextMenuPrimitive.Group>) {
  return (
    <ContextMenuPrimitive.Group data-slot="context-menu-group" {...props} />
  );
}

function ContextMenuItem({
  className,
  inset,
  variant = 'default',
  ...props
}: React.ComponentProps<typeof ContextMenuPrimitive.Item> & {
  inset?: boolean;
  variant?: 'default' | 'destructive';
}) {
  const size = useContextMenuSize();
  const isLg = size === 'lg';
  const padding = inset
    ? isLg
      ? 'pl-9 pr-3 py-2'
      : 'pl-7 pr-2 py-2'
    : isLg
      ? 'px-3 py-2'
      : 'p-2';

  return (
    <ContextMenuPrimitive.Item
      data-slot="context-menu-item"
      data-inset={inset}
      data-variant={variant}
      data-size={size}
      className={cn(
        isLg ? 'paragraph-large-primary' : 'paragraph-regular-primary',
        'text-fg-secondary data-[highlighted]:bg-stateslayer-overlay-hover data-[highlighted]:text-fg-primary active:bg-stateslayer-overlay-pressed [&_svg:not([class*="text-"])]:text-fg-tertiary data-[disabled]:text-fg-disabled relative flex cursor-pointer items-center gap-2 outline-none select-none data-[disabled]:pointer-events-none [&_svg]:pointer-events-none [&_svg]:shrink-0',
        padding,
        'data-[variant=destructive]:text-destructive data-[variant=destructive]:data-[highlighted]:text-destructive data-[variant=destructive]:[&_svg:not([class*="text-"])]:!text-destructive',
        className,
      )}
      {...props}
    />
  );
}

function ContextMenuCheckboxItem({
  className,
  children,
  checked,
  ...props
}: React.ComponentProps<typeof ContextMenuPrimitive.CheckboxItem>) {
  const size = useContextMenuSize();
  const isLg = size === 'lg';

  return (
    <ContextMenuPrimitive.CheckboxItem
      data-slot="context-menu-checkbox-item"
      data-size={size}
      className={cn(
        isLg ? 'paragraph-large-primary' : 'paragraph-regular-primary',
        'text-fg-secondary data-[highlighted]:bg-stateslayer-overlay-hover data-[highlighted]:text-fg-primary active:bg-stateslayer-overlay-pressed data-[disabled]:text-fg-disabled group relative flex cursor-pointer items-center gap-2 outline-none select-none data-[disabled]:pointer-events-none [&_svg]:pointer-events-none [&_svg]:shrink-0',
        isLg ? 'py-2 pr-3 pl-9' : 'py-2 pr-2 pl-7',
        className,
      )}
      checked={checked}
      {...props}>
      <span className="pointer-events-none absolute left-1 flex size-4 items-center justify-center">
        <span className="border-stroke-primary group-data-[disabled]:border-stroke-tertiary relative flex size-4 items-center justify-center border bg-transparent">
          <ContextMenuPrimitive.ItemIndicator className="text-fill-active group-data-[disabled]:text-fill-disabled absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2">
            <CheckboxItemMark />
          </ContextMenuPrimitive.ItemIndicator>
        </span>
      </span>
      {children}
    </ContextMenuPrimitive.CheckboxItem>
  );
}

function ContextMenuRadioGroup({
  ...props
}: React.ComponentProps<typeof ContextMenuPrimitive.RadioGroup>) {
  return (
    <ContextMenuPrimitive.RadioGroup
      data-slot="context-menu-radio-group"
      {...props}
    />
  );
}

function ContextMenuRadioItem({
  className,
  children,
  ...props
}: React.ComponentProps<typeof ContextMenuPrimitive.RadioItem>) {
  const size = useContextMenuSize();
  const isLg = size === 'lg';

  return (
    <ContextMenuPrimitive.RadioItem
      data-slot="context-menu-radio-item"
      data-size={size}
      className={cn(
        isLg ? 'paragraph-large-primary' : 'paragraph-regular-primary',
        'text-fg-secondary data-[highlighted]:bg-stateslayer-overlay-hover data-[highlighted]:text-fg-primary active:bg-stateslayer-overlay-pressed data-[disabled]:text-fg-disabled group relative flex cursor-pointer items-center gap-2 outline-none select-none data-[disabled]:pointer-events-none [&_svg]:pointer-events-none [&_svg]:shrink-0',
        isLg ? 'py-2 pr-3 pl-9' : 'py-2 pr-2 pl-7',
        className,
      )}
      {...props}>
      <span className="pointer-events-none absolute left-1 flex size-4 items-center justify-center">
        <span className="border-stroke-primary group-data-[disabled]:border-stroke-tertiary relative flex size-4 items-center justify-center rounded-full border bg-transparent">
          <ContextMenuPrimitive.ItemIndicator className="flex items-center justify-center">
            <span
              aria-hidden
              className="bg-fill-active group-data-[disabled]:bg-fill-disabled size-2 rounded-full"
            />
          </ContextMenuPrimitive.ItemIndicator>
        </span>
      </span>
      {children}
    </ContextMenuPrimitive.RadioItem>
  );
}

function ContextMenuLabel({
  className,
  inset,
  ...props
}: React.ComponentProps<typeof ContextMenuPrimitive.Label> & {
  inset?: boolean;
}) {
  const size = useContextMenuSize();

  return (
    <ContextMenuPrimitive.Label
      data-slot="context-menu-label"
      data-inset={inset}
      data-size={size}
      className={cn(
        'text-fg-secondary label-regular-primary flex h-9 items-center p-2 data-[inset]:pl-8',
        className,
      )}
      {...props}
    />
  );
}

function ContextMenuSeparator({
  className,
  ...props
}: React.ComponentProps<typeof ContextMenuPrimitive.Separator>) {
  return (
    <div
      className={cn(
        'pointer-events-none -mx-1 flex h-2 shrink-0 flex-col',
        className,
      )}
      style={{ width: 'calc(100% + 8px)' }}>
      <ContextMenuPrimitive.Separator
        className="border-stroke-divider h-1 w-full shrink-0 border-0 border-b border-solid bg-transparent"
        data-slot="context-menu-separator"
        {...props}
      />
      <div aria-hidden className="h-1 w-full shrink-0" />
    </div>
  );
}

function ContextMenuShortcut({
  className,
  ...props
}: React.ComponentProps<'span'>) {
  return (
    <span
      data-slot="context-menu-shortcut"
      className={cn(
        'paragraph-regular-primary text-fg-tertiary ml-auto',
        className,
      )}
      {...props}
    />
  );
}

function ContextMenuSub({
  ...props
}: React.ComponentProps<typeof ContextMenuPrimitive.Sub>) {
  return <ContextMenuPrimitive.Sub data-slot="context-menu-sub" {...props} />;
}

function ContextMenuSubTrigger({
  className,
  inset,
  children,
  ...props
}: React.ComponentProps<typeof ContextMenuPrimitive.SubTrigger> & {
  inset?: boolean;
}) {
  const size = useContextMenuSize();
  const isLg = size === 'lg';
  const paddingBySize = {
    default: { inset: 'pl-7 pr-1 py-2', default: 'pl-2 pr-1 py-2' },
    lg: { inset: 'pl-9 pr-2 py-2', default: 'pl-3 pr-2 py-2' },
  } as const;
  const padding = paddingBySize[size][inset ? 'inset' : 'default'];

  return (
    <ContextMenuPrimitive.SubTrigger
      data-slot="context-menu-sub-trigger"
      data-inset={inset}
      data-size={size}
      className={cn(
        isLg ? 'paragraph-large-primary' : 'paragraph-regular-primary',
        'text-fg-secondary data-[highlighted]:bg-stateslayer-overlay-hover data-[highlighted]:text-fg-primary data-[state=open]:bg-stateslayer-overlay-hover data-[state=open]:text-fg-primary [&_svg:not([class*="text-"])]:text-fg-tertiary flex cursor-pointer items-center gap-2 outline-none select-none [&_svg]:pointer-events-none [&_svg]:shrink-0',
        padding,
        className,
      )}
      {...props}>
      {children}
      <IconShell className="ml-auto" size={isLg ? 'default' : 'sm'}>
        <Icon icon="chevron_right" />
      </IconShell>
    </ContextMenuPrimitive.SubTrigger>
  );
}

type ContextMenuSubContentProps = React.ComponentProps<
  typeof ContextMenuPrimitive.SubContent
> & {
  children?: React.ReactNode;
  size?: ContextMenuSize;
};

function ContextMenuSubContent({
  className,
  size,
  ...props
}: ContextMenuSubContentProps) {
  const parentSize = useContextMenuSize();
  const effectiveSize = size ?? parentSize;

  return (
    <ContextMenuSizeContext.Provider value={effectiveSize}>
      <ContextMenuPrimitive.SubContent
        data-slot="context-menu-sub-content"
        data-size={effectiveSize}
        className={cn(
          'bg-fill-active-inverse text-fg-primary shadow-elevation-2 data-[state=open]:animate-in data-[state=closed]:animate-out data-[state=closed]:fade-out-0 data-[state=open]:fade-in-0 data-[state=closed]:zoom-out-95 data-[state=open]:zoom-in-95 data-[side=bottom]:slide-in-from-top-2 data-[side=left]:slide-in-from-right-2 data-[side=right]:slide-in-from-left-2 data-[side=top]:slide-in-from-bottom-2 z-50 origin-(--radix-context-menu-content-transform-origin) overflow-hidden',
          effectiveSize === 'lg' ? 'px-1 py-2' : 'p-1',
          className,
        )}
        {...props}
      />
    </ContextMenuSizeContext.Provider>
  );
}

export {
  ContextMenu,
  ContextMenuPortal,
  ContextMenuTrigger,
  ContextMenuContent,
  ContextMenuGroup,
  ContextMenuLabel,
  ContextMenuItem,
  ContextMenuCheckboxItem,
  ContextMenuRadioGroup,
  ContextMenuRadioItem,
  ContextMenuSeparator,
  ContextMenuShortcut,
  ContextMenuSub,
  ContextMenuSubTrigger,
  ContextMenuSubContent,
};

import * as React from 'react';

import {
  ContextMenu,
  ContextMenuCheckboxItem,
  ContextMenuContent,
  ContextMenuGroup,
  ContextMenuItem,
  ContextMenuLabel,
  ContextMenuPortal,
  ContextMenuRadioGroup,
  ContextMenuRadioItem,
  ContextMenuSeparator,
  ContextMenuShortcut,
  ContextMenuSub,
  ContextMenuSubContent,
  ContextMenuSubTrigger,
  ContextMenuTrigger,
} from '@/components/ui/context-menu';
import { Icon } from '@/components/ui/icon';

/** Pass on `ContextMenuContent` / `ContextMenuSubContent` via `className`. */
const CONTEXT_MENU_PANEL_CLASS = 'w-[256px] max-w-[256px] min-w-[256px]';

const TRIGGER_CLASS =
  'border-stroke-tertiary text-fg-secondary paragraph-regular-primary flex h-[150px] w-[300px] items-center justify-center border border-dashed select-none';

function ContextMenuTriggerArea({
  children,
  label = 'Right-click here',
}: {
  children: React.ReactNode;
  label?: string;
}) {
  return (
    <ContextMenu>
      <ContextMenuTrigger className={TRIGGER_CLASS}>{label}</ContextMenuTrigger>

      {children}
    </ContextMenu>
  );
}

// ============================================================================
// Example Components
// ============================================================================

/**
 * Basic context menu with labels and separators
 */
export function ContextMenuDemo() {
  return (
    <ContextMenuTriggerArea>
      <ContextMenuContent className={CONTEXT_MENU_PANEL_CLASS}>
        <ContextMenuGroup>
          <ContextMenuLabel>My Account</ContextMenuLabel>
          <ContextMenuItem>Profile</ContextMenuItem>
          <ContextMenuItem>Billing</ContextMenuItem>
          <ContextMenuItem>Settings</ContextMenuItem>
        </ContextMenuGroup>

        <ContextMenuSeparator />

        <ContextMenuItem>GitHub</ContextMenuItem>
        <ContextMenuItem>Support</ContextMenuItem>
        <ContextMenuItem disabled>API</ContextMenuItem>
      </ContextMenuContent>
    </ContextMenuTriggerArea>
  );
}

/**
 * Context menu with keyboard shortcut hints
 */
export function ContextMenuWithShortcuts() {
  return (
    <ContextMenuTriggerArea>
      <ContextMenuContent className={CONTEXT_MENU_PANEL_CLASS}>
        <ContextMenuGroup>
          <ContextMenuLabel>My Account</ContextMenuLabel>

          <ContextMenuItem>
            Profile
            <ContextMenuShortcut>⇧⌘P</ContextMenuShortcut>
          </ContextMenuItem>

          <ContextMenuItem>
            Billing
            <ContextMenuShortcut>⌘B</ContextMenuShortcut>
          </ContextMenuItem>

          <ContextMenuItem>
            Settings
            <ContextMenuShortcut>⌘S</ContextMenuShortcut>
          </ContextMenuItem>
        </ContextMenuGroup>

        <ContextMenuSeparator />

        <ContextMenuItem>
          Log out
          <ContextMenuShortcut>⇧⌘Q</ContextMenuShortcut>
        </ContextMenuItem>
      </ContextMenuContent>
    </ContextMenuTriggerArea>
  );
}

/**
 * Context menu with icons alongside labels
 */
export function ContextMenuWithIcons() {
  return (
    <ContextMenuTriggerArea>
      <ContextMenuContent className={CONTEXT_MENU_PANEL_CLASS}>
        <ContextMenuItem>
          <Icon icon="person" className="size-4" />
          Profile
        </ContextMenuItem>

        <ContextMenuItem>
          <Icon icon="attach_money" className="size-4" />
          Billing
        </ContextMenuItem>

        <ContextMenuItem>
          <Icon icon="key" className="size-4" />
          Settings
        </ContextMenuItem>

        <ContextMenuSeparator />

        <ContextMenuItem variant="destructive">
          <Icon icon="close" className="size-4" />
          Log out
        </ContextMenuItem>
      </ContextMenuContent>
    </ContextMenuTriggerArea>
  );
}

/**
 * Nested submenus for secondary actions
 */
export function ContextMenuWithSubmenu() {
  return (
    <ContextMenuTriggerArea>
      <ContextMenuContent className={CONTEXT_MENU_PANEL_CLASS}>
        <ContextMenuGroup>
          <ContextMenuItem>
            <Icon icon="person" className="size-4" />
            Team
          </ContextMenuItem>

          <ContextMenuSub>
            <ContextMenuSubTrigger>
              <Icon icon="send" className="size-4" />
              Invite users
            </ContextMenuSubTrigger>

            <ContextMenuPortal>
              <ContextMenuSubContent className={CONTEXT_MENU_PANEL_CLASS}>
                <ContextMenuItem>
                  <Icon icon="mail" className="size-4" />
                  Email
                </ContextMenuItem>

                <ContextMenuItem>Message</ContextMenuItem>

                <ContextMenuSeparator />

                <ContextMenuItem>More&hellip;</ContextMenuItem>
              </ContextMenuSubContent>
            </ContextMenuPortal>
          </ContextMenuSub>

          <ContextMenuItem>
            New Team
            <ContextMenuShortcut>⌘+T</ContextMenuShortcut>
          </ContextMenuItem>
        </ContextMenuGroup>
      </ContextMenuContent>
    </ContextMenuTriggerArea>
  );
}

/**
 * Checkbox items for toggling options
 */
export function ContextMenuWithCheckboxes() {
  const [showStatusBar, setShowStatusBar] = React.useState(true);
  const [showActivityBar, setShowActivityBar] = React.useState(false);
  const [showPanel, setShowPanel] = React.useState(false);

  return (
    <ContextMenuTriggerArea>
      <ContextMenuContent className={CONTEXT_MENU_PANEL_CLASS}>
        <ContextMenuGroup>
          <ContextMenuLabel>Appearance</ContextMenuLabel>

          <ContextMenuCheckboxItem
            checked={showStatusBar}
            onCheckedChange={setShowStatusBar}>
            Status Bar
          </ContextMenuCheckboxItem>

          <ContextMenuCheckboxItem
            checked={showActivityBar}
            onCheckedChange={setShowActivityBar}
            disabled>
            Activity Bar
          </ContextMenuCheckboxItem>

          <ContextMenuCheckboxItem
            checked={showPanel}
            onCheckedChange={setShowPanel}>
            Panel
          </ContextMenuCheckboxItem>
        </ContextMenuGroup>
      </ContextMenuContent>
    </ContextMenuTriggerArea>
  );
}

/**
 * Radio group for exclusive choices
 */
export function ContextMenuWithRadioGroup() {
  const [position, setPosition] = React.useState('bottom');

  return (
    <ContextMenuTriggerArea>
      <ContextMenuContent className={CONTEXT_MENU_PANEL_CLASS}>
        <ContextMenuGroup>
          <ContextMenuLabel>Panel Position</ContextMenuLabel>

          <ContextMenuRadioGroup value={position} onValueChange={setPosition}>
            <ContextMenuRadioItem value="top">Top</ContextMenuRadioItem>
            <ContextMenuRadioItem value="bottom">Bottom</ContextMenuRadioItem>
            <ContextMenuRadioItem value="right">Right</ContextMenuRadioItem>
          </ContextMenuRadioGroup>
        </ContextMenuGroup>
      </ContextMenuContent>
    </ContextMenuTriggerArea>
  );
}

/**
 * Larger touch targets and typography
 */
export function ContextMenuLarge() {
  return (
    <ContextMenuTriggerArea>
      <ContextMenuContent size="lg" className={CONTEXT_MENU_PANEL_CLASS}>
        <ContextMenuGroup>
          <ContextMenuItem>
            <Icon icon="person" className="size-6" />
            Profile
          </ContextMenuItem>

          <ContextMenuItem>
            <Icon icon="attach_money" className="size-6" />
            Billing
            <ContextMenuShortcut>⌘B</ContextMenuShortcut>
          </ContextMenuItem>

          <ContextMenuSub>
            <ContextMenuSubTrigger inset>Invite users</ContextMenuSubTrigger>

            <ContextMenuPortal>
              <ContextMenuSubContent
                size="lg"
                className={CONTEXT_MENU_PANEL_CLASS}>
                <ContextMenuItem>Email</ContextMenuItem>
                <ContextMenuItem>Message</ContextMenuItem>
              </ContextMenuSubContent>
            </ContextMenuPortal>
          </ContextMenuSub>
        </ContextMenuGroup>
      </ContextMenuContent>
    </ContextMenuTriggerArea>
  );
}

/**
 * Destructive variant for irreversible actions
 */
export function ContextMenuDestructive() {
  return (
    <ContextMenuTriggerArea label="Right-click for actions">
      <ContextMenuContent className={CONTEXT_MENU_PANEL_CLASS}>
        <ContextMenuGroup>
          <ContextMenuItem>
            <Icon icon="edit" className="size-4" />
            Edit
          </ContextMenuItem>

          <ContextMenuItem>
            <Icon icon="send" className="size-4" />
            Share
          </ContextMenuItem>
        </ContextMenuGroup>

        <ContextMenuSeparator />

        <ContextMenuGroup>
          <ContextMenuItem variant="destructive">
            <Icon icon="delete" className="size-4" />
            Delete
          </ContextMenuItem>
        </ContextMenuGroup>
      </ContextMenuContent>
    </ContextMenuTriggerArea>
  );
}

// ============================================================================
// Example Metadata
// ============================================================================

export const examples = [
  {
    name: 'ContextMenuDemo',
    title: 'Default',
    description: 'Basic context menu with labels and separators.',
  },
  {
    name: 'ContextMenuWithShortcuts',
    title: 'Shortcuts',
    description: 'Context menu items with keyboard shortcut hints.',
  },
  {
    name: 'ContextMenuWithIcons',
    title: 'With Icons',
    description: 'Context items combined with icons for quick scanning.',
  },
  {
    name: 'ContextMenuWithSubmenu',
    title: 'Submenu',
    description: 'Nested submenus for secondary actions.',
  },
  {
    name: 'ContextMenuWithCheckboxes',
    title: 'Checkboxes',
    description: 'Checkbox items for toggling multiple options.',
  },
  {
    name: 'ContextMenuWithRadioGroup',
    title: 'Radio Group',
    description: 'Radio group for exclusive choices.',
  },
  {
    name: 'ContextMenuLarge',
    title: 'Large',
    description: 'Larger touch targets and typography.',
  },
  {
    name: 'ContextMenuDestructive',
    title: 'Destructive',
    description: 'Destructive variant for irreversible actions.',
  },
];

// ============================================================================
// Legacy Format (for backwards compatibility)
// ============================================================================

export const contextMenu = {
  name: 'context-menu',
  components: {
    Default: <ContextMenuDemo />,
    Shortcuts: <ContextMenuWithShortcuts />,
    'With Icons': <ContextMenuWithIcons />,
    Submenu: <ContextMenuWithSubmenu />,
    Checkboxes: <ContextMenuWithCheckboxes />,
    'Radio Group': <ContextMenuWithRadioGroup />,
    Large: <ContextMenuLarge />,
    Destructive: <ContextMenuDestructive />,
  },
};
